questions.solution:
import math

PATCH = 28  # pixels per side of one visual token


def visual_tokens(width, height):
    """Visual tokens of an image: one per 28 x 28 patch, each side rounded up."""
    return math.ceil(width / PATCH) * math.ceil(height / PATCH)


def fits(width, height, max_edge=1568, max_tokens=1568):
    """True if the image is within both limits and would be sent without resizing."""
    return (width <= max_edge and height <= max_edge
            and visual_tokens(width, height) <= max_tokens)
